// Receive BME280 MQTT data
let sensor = msg.payload;

// Standardize sensor values
let sensorData = {
    temperature: Number(sensor.temperature_c),
    humidity: Number(sensor.humidity_pct),
    pressure: Number(sensor.pressure_hpa),
    timestamp: Date.now()
};

// Store latest sensor reading
flow.set("sensorData", sensorData);

msg.source = "bme280";
msg.payload = sensorData;

return msg;

let sensor = flow.get("sensorData");
let weather = flow.get("weatherData");

// Wait until both sources have provided data
if (!sensor || !weather) {
    node.warn("Waiting for sensor and weather data");
    return null;
}

let result = {
    sensor_temperature: sensor.temperature,
    weather_temperature: weather.temperature,

    sensor_humidity: sensor.humidity,
    weather_humidity: weather.humidity,

    sensor_pressure: sensor.pressure,
    weather_pressure: weather.pressure,

    temperature_difference:
        Number((sensor.temperature - weather.temperature).toFixed(2)),

    humidity_difference:
        Number((sensor.humidity - weather.humidity).toFixed(2)),

    pressure_difference:
        Number((sensor.pressure - weather.pressure).toFixed(2))
};

msg.payload = result;

return msg;

/* =====================================
   WEATHER API DATA EXTRACTION
   ===================================== */

let weather = msg.payload;

if (
    !weather ||
    !weather.main ||
    !weather.wind
) {
    node.error("Invalid weather API response", msg);
    return null;
}

let result = {
    city: weather.name || "Unknown",
    temperature: Number(weather.main.temp),
    feels_like: Number(weather.main.feels_like),
    humidity: Number(weather.main.humidity),
    pressure: Number(weather.main.pressure),
    wind_speed: Number(weather.wind.speed),
    timestamp: Date.now()
};

if (
    ![
        result.temperature,
        result.humidity,
        result.pressure,
        result.feels_like,
        result.wind_speed
    ].every(Number.isFinite) ||
    result.humidity < 0 ||
    result.humidity > 100
) {
    node.error("Invalid weather values", msg);
    return null;
}

msg.payload = result;
msg.source = "weather_api";

return msg;

/* =====================================
   WEATHER API HEAT INDEX
   ===================================== */

let data = msg.payload;

if (
    !data ||
    !Number.isFinite(Number(data.temperature)) ||
    !Number.isFinite(Number(data.humidity)) ||
    Number(data.humidity) < 0 ||
    Number(data.humidity) > 100
) {
    node.error("Invalid weather data for heat index", msg);
    return null;
}

let T = Number(data.temperature);
let RH = Number(data.humidity);

let F = T * 9/5 + 32;

// Initial heat index estimate
let HI = 0.5 * (
    F + 61 + ((F - 68) * 1.2) + (RH * 0.094)
);

HI = (HI + F) / 2;

// NOAA Rothfusz regression
if (HI >= 80) {
    HI = -42.379
        + 2.04901523 * F
        + 10.14333127 * RH
        - 0.22475541 * F * RH
        - 0.00683783 * F * F
        - 0.05481717 * RH * RH
        + 0.00122874 * F * F * RH
        + 0.00085282 * F * RH * RH
        - 0.00000199 * F * F * RH * RH;

    if (RH < 13 && F >= 80 && F <= 112) {
        HI -= ((13 - RH) / 4) *
            Math.sqrt((17 - Math.abs(F - 95)) / 17);
    } else if (RH > 85 && F >= 80 && F <= 87) {
        HI += ((RH - 85) / 10) *
            ((87 - F) / 5);
    }
}

let heatIndex = (HI - 32) * 5/9;

let risk;

if (HI < 80) {
    risk = "Normal";
} else if (HI < 90) {
    risk = "Caution";
} else if (HI < 103) {
    risk = "Extreme Caution";
} else if (HI < 125) {
    risk = "Danger";
} else {
    risk = "Extreme Danger";
}

data.heat_index_c = Number(heatIndex.toFixed(2));
data.heat_risk = risk;

msg.payload = data;

return msg;

/* ============================================
   HEAT MONITORING
   & RICE CROP ADVISORY
   ============================================ */

// 1. GET COMPARISON DATA

let data = msg.payload;

if (!data || typeof data !== "object") {
    node.warn("Invalid comparison data");
    return null;
}


// 2. EXTRACT SENSOR READINGS

let temperature = Number(data.sensor_temperature);
let humidity = Number(data.sensor_humidity);
let pressure = Number(data.sensor_pressure);

let heatIndex = Number(data.combined_heat_index_c);
let heatRisk = data.combined_heat_risk;


// 3. INITIALIZE OUTPUTS

let alertLevel = "WAITING";

let irrigationAdvisory =
    "Waiting for fresh environmental readings.";

let heatIndexAdvisory =
    "Waiting for valid heat index data.";

let temperatureMessage = "UNAVAILABLE";


// 4. VALIDATE SENSOR READINGS

let sensorReady =
    data.sensor_status === "SENSOR READY" &&
    Number.isFinite(temperature) &&
    Number.isFinite(humidity) &&
    Number.isFinite(pressure) &&
    temperature >= -40 && temperature <= 85 &&
    humidity >= 0 && humidity <= 100 &&
    pressure >= 300 && pressure <= 1200;


// 5. RICE CROP ENVIRONMENTAL ADVISORY

if (!sensorReady) {

    alertLevel = "WAITING";

    irrigationAdvisory =
        "Waiting for valid BME280 readings. " +
        "Check sensor connectivity and data availability.";

} else {

    // HIGH: Hot and relatively dry conditions

    if (temperature >= 30 && humidity <= 60) {

        alertLevel = "HIGH";

        irrigationAdvisory =
            "Potentially increased atmospheric drying detected. " +
            "Rice plants may experience increased water loss. " +
            "Check leaf condition and field water availability. " +
            "Review irrigation requirements promptly.";

    }

    // MODERATE: Warm conditions with relatively lower humidity

    else if (temperature >= 28 && humidity <= 70) {

        alertLevel = "MODERATE";

        irrigationAdvisory =
            "Warm conditions detected. Rice crop water demand " +
            "may increase. Monitor crop growth, leaf condition " +
            "and field water availability. Review the irrigation schedule.";

    }

    // MONITOR: One environmental condition needs attention

    else if (temperature >= 30 || humidity <= 45) {

        alertLevel = "MONITOR";

        irrigationAdvisory =
            "Environmental conditions need attention. " +
            "Observe rice leaves for wilting or drying and " +
            "check field water availability.";

    }

    // NORMAL: No elevated signal from current thresholds

    else {

        alertLevel = "NORMAL";

        irrigationAdvisory =
            "No elevated atmospheric drying signal detected " +
            "by the current thresholds. Continue routine rice " +
            "crop observation and planned irrigation practices.";
    }
}


// 6. TEMPERATURE CONDITION

if (Number.isFinite(temperature)) {

    if (temperature < 10) {
        temperatureMessage = "VERY COLD";

    } else if (temperature < 18) {
        temperatureMessage = "COLD";

    } else if (temperature < 25) {
        temperatureMessage = "COOL";

    } else if (temperature < 35) {
        temperatureMessage = "WARM";

    } else {
        temperatureMessage = "HOT";
    }
}


// 7. NOAA HEAT INDEX ADVISORY

if (
    Number.isFinite(heatIndex) &&
    typeof heatRisk === "string"
) {

    if (heatRisk === "Normal") {

        heatIndexAdvisory =
            "Feels-like heat is below the NOAA caution level. " +
            "Continue normal heat-safety precautions.";

    } else if (heatRisk === "Caution") {

        heatIndexAdvisory =
            "It may feel hot due to temperature and humidity. " +
            "Stay hydrated and take breaks during outdoor work.";

    } else if (heatRisk === "Extreme Caution") {

        heatIndexAdvisory =
            "It may feel very hot. Reduce prolonged outdoor activity, " +
            "take frequent breaks and stay hydrated.";

    } else if (heatRisk === "Danger") {

        heatIndexAdvisory =
            "Dangerously hot conditions are possible. Avoid strenuous " +
            "outdoor work and stay in a cool place.";

    } else if (heatRisk === "Extreme Danger") {

        heatIndexAdvisory =
            "Extremely dangerous heat conditions are possible. " +
            "Avoid outdoor exposure and stay in a cool place. " +
            "Follow local heat-safety guidance.";

    } else {

        heatIndexAdvisory =
            "Heat-risk classification is unavailable. Check the data.";
    }

} else {

    heatIndexAdvisory =
        "Heat index is unavailable. Waiting for valid sensor " +
        "and weather data.";
}


// 8. ATTACH RESULTS

data.irrigation_alert_level = alertLevel;

data.irrigation_advisory = irrigationAdvisory;

data.temperature_message = temperatureMessage;

data.heat_index_advisory = heatIndexAdvisory;

data.environmental_monitoring_status =
    sensorReady ? "SENSOR DATA VALID" : "SENSOR DATA UNAVAILABLE";

data.pressure_monitoring =
    Number.isFinite(pressure) ? pressure : null;


// 9. SEND OUTPUT

msg.payload = data;

return msg;

/* =====================================
   STORE LATEST WEATHER DATA
   ===================================== */

flow.set("weatherData", msg.payload);

msg.source = "weather_api";

return msg;

/* =====================================
   BME280 SENSOR DATA PROCESSING
   ===================================== */

let sensor = msg.payload;

let temperature = Number(sensor.temperature_c);
let humidity = Number(sensor.humidity_pct);
let pressure = Number(sensor.pressure_hpa);

// Validate readings
if (
    !Number.isFinite(temperature) ||
    !Number.isFinite(humidity) ||
    !Number.isFinite(pressure) ||
    temperature < -40 || temperature > 85 ||
    humidity < 0 || humidity > 100 ||
    pressure < 300 || pressure > 1200
) {
    node.warn("Invalid BME280 sensor data");
    return null;
}

// Convert Celsius to Fahrenheit
let T = temperature * 9/5 + 32;
let R = humidity;

// Initial heat index estimate
let HI = 0.5 * (
    T + 61 + ((T - 68) * 1.2) + (R * 0.094)
);

HI = (HI + T) / 2;

// NOAA Rothfusz regression
if (HI >= 80) {
    HI = -42.379
        + 2.04901523 * T
        + 10.14333127 * R
        - 0.22475541 * T * R
        - 0.00683783 * T * T
        - 0.05481717 * R * R
        + 0.00122874 * T * T * R
        + 0.00085282 * T * R * R
        - 0.00000199 * T * T * R * R;

    // Low humidity adjustment
    if (R < 13 && T >= 80 && T <= 112) {
        HI -= ((13 - R) / 4) *
            Math.sqrt((17 - Math.abs(T - 95)) / 17);
    }

    // High humidity adjustment
    else if (R > 85 && T >= 80 && T <= 87) {
        HI += ((R - 85) / 10) *
            ((87 - T) / 5);
    }
}

// Fahrenheit to Celsius
let heatIndexC = (HI - 32) * 5/9;

// Heat risk classification
let risk;

if (HI < 80) {
    risk = "Normal";
} else if (HI < 90) {
    risk = "Caution";
} else if (HI < 103) {
    risk = "Extreme Caution";
} else if (HI < 125) {
    risk = "Danger";
} else {
    risk = "Extreme Danger";
}

// Standardized sensor data
let sensorData = {
    temperature: temperature,
    humidity: humidity,
    pressure: pressure,
    heat_index_c: Number(heatIndexC.toFixed(2)),
    heat_risk: risk,
    timestamp: Date.now()
};

// Store latest sensor reading
flow.set("sensorData", sensorData);

msg.source = "bme280";
msg.payload = sensorData;

return msg;

/* ============================================
   COMPARISON ENGINE
   STM32 BME280 vs WEATHER API
   ============================================ */

// 1. GET LATEST DATA

let sensor = flow.get("sensorData");
let weather = flow.get("weatherData");

let now = Date.now();

// Data update interval: 60 seconds
// Maximum allowed data age: 120 seconds
const MAX_AGE = 120 * 1000;


// 2. INITIALIZE RESULT

let result = {
    comparison_status: "WAITING",
    sensor_status: "WAITING",
    weather_status: "WAITING"
};


// 3. VALIDATE SENSOR DATA

if (!sensor) {
    result.sensor_status = "NO SENSOR DATA";

} else if (
    !Number.isFinite(sensor.timestamp) ||
    now - sensor.timestamp > MAX_AGE ||
    now - sensor.timestamp < 0
) {
    result.sensor_status = "SENSOR DATA STALE";

} else {
    result.sensor_status = "SENSOR READY";
}


// 4. VALIDATE WEATHER API DATA

if (!weather) {
    result.weather_status = "NO WEATHER DATA";

} else if (
    !Number.isFinite(weather.timestamp) ||
    now - weather.timestamp > MAX_AGE ||
    now - weather.timestamp < 0
) {
    result.weather_status = "WEATHER DATA STALE";

} else {
    result.weather_status = "WEATHER READY";
}


// 5. CHECK BOTH DATA SOURCES

if (
    result.sensor_status !== "SENSOR READY" ||
    result.weather_status !== "WEATHER READY"
) {
    result.comparison_status = "DATA UNAVAILABLE";
    msg.payload = result;
    return msg;
}


// 6. EXTRACT SENSOR VALUES

let st = Number(sensor.temperature);
let sh = Number(sensor.humidity);
let sp = Number(sensor.pressure);
let shi = Number(sensor.heat_index_c);


// 7. EXTRACT WEATHER API VALUES

let wt = Number(weather.temperature);
let wh = Number(weather.humidity);
let wp = Number(weather.pressure);
let whi = Number(weather.heat_index_c);


// 8. VALIDATE ALL READINGS

if (
    ![st, sh, sp, shi, wt, wh, wp, whi].every(Number.isFinite) ||
    sh < 0 || sh > 100 ||
    wh < 0 || wh > 100
) {
    result.comparison_status = "INVALID DATA";
    msg.payload = result;
    return msg;
}


// 9. CALCULATE DIFFERENCES

let td = st - wt;
let hd = sh - wh;
let pd = sp - wp;
let hid = shi - whi;


// 10. IDENTIFY HIGHER HEAT INDEX SOURCE

let hotterSource = "EQUAL";

if (shi > whi) {
    hotterSource = "STM32 SENSOR";

} else if (whi > shi) {
    hotterSource = "WEATHER API";
}


// 11. SELECT HIGHER HEAT INDEX

// Conservative screening approach
let combinedHI = Math.max(shi, whi);

// Convert Celsius to Fahrenheit
let hiF = combinedHI * 9/5 + 32;


// 12. CLASSIFY NOAA HEAT RISK

let combinedRisk;

if (hiF < 80) {
    combinedRisk = "Normal";

} else if (hiF < 90) {
    combinedRisk = "Caution";

} else if (hiF < 103) {
    combinedRisk = "Extreme Caution";

} else if (hiF < 125) {
    combinedRisk = "Danger";

} else {
    combinedRisk = "Extreme Danger";
}


// 13. TEMPERATURE CONDITION MESSAGE

// Based on local STM32 sensor temperature

let temperatureMessage;

if (st < 10) {
    temperatureMessage = "VERY COLD";

} else if (st < 18) {
    temperatureMessage = "COLD";

} else if (st < 25) {
    temperatureMessage = "COOL";

} else if (st < 35) {
    temperatureMessage = "WARM";

} else {
    temperatureMessage = "HOT";
}


// 14. PREPARE FINAL OUTPUT

result = {

    // Data status
    comparison_status: "READY",
    sensor_status: "SENSOR READY",
    weather_status: "WEATHER READY",

    // Temperature
    sensor_temperature: st,
    weather_temperature: wt,
    temperature_difference: Number(td.toFixed(2)),

    // Humidity
    sensor_humidity: sh,
    weather_humidity: wh,
    humidity_difference: Number(hd.toFixed(2)),

    // Pressure
    sensor_pressure: sp,
    weather_pressure: wp,
    pressure_difference: Number(pd.toFixed(2)),

    // Heat Index
    sensor_heat_index: shi,
    weather_heat_index: whi,
    heat_index_difference: Number(hid.toFixed(2)),

    // Higher heat index source
    hotter_source: hotterSource,

    // Combined heat screening
    combined_heat_index_c: Number(combinedHI.toFixed(2)),
    combined_heat_risk: combinedRisk,

    // Local temperature condition
    temperature_message: temperatureMessage,

    // Last comparison time
    timestamp: now
};


// 15. SEND OUTPUT

msg.payload = result;

return msg;

/* =====================================
   MOCK BME280 DATA GENERATOR
   Temperature, Humidity, Pressure
   ===================================== */

let p = msg.payload;

if (!p ||
    !Number.isFinite(Number(p.temperature_c)) ||
    !Number.isFinite(Number(p.humidity_pct)) ||
    !Number.isFinite(Number(p.pressure_hpa))) {
    node.warn("Invalid mock BME280 input");
    return null;
}

let current = flow.get("mockBME280") || {
    temperature_c: Number(p.temperature_c),
    humidity_pct: Number(p.humidity_pct),
    pressure_hpa: Number(p.pressure_hpa)
};

function vary(value, change, min, max) {
    let next = value + (Math.random() - 0.5) * change;
    return Number(Math.max(min, Math.min(max, next)).toFixed(2));
}

current.temperature_c =
    vary(current.temperature_c, 0.8, 20, 45);

current.humidity_pct =
    vary(current.humidity_pct, 2, 20, 100);

current.pressure_hpa =
    vary(current.pressure_hpa, 1.5, 950, 1050);

flow.set("mockBME280", current);

msg.payload = {
    temperature_c: current.temperature_c,
    humidity_pct: current.humidity_pct,
    pressure_hpa: current.pressure_hpa
};

return msg;

/* =====================================
   PARSE STM32 TEXT INTO JSON
   ===================================== */

let raw = msg.payload;

// Convert payload to string
if (typeof raw !== "string") {
    node.warn("Expected STM32 text message");
    return null;
}

// Extract temperature, pressure and humidity
let match = raw.match(
    /Temperature:\s*(-?\d+(?:\.\d+)?)\s*C\s*,\s*Pressure:\s*(-?\d+(?:\.\d+)?)\s*hPa\s*,\s*Humidity:\s*(-?\d+(?:\.\d+)?)\s*%/i
);

if (!match) {
    node.warn("Invalid STM32 message format: " + raw);
    return null;
}

let temperature = Number(match[1]);
let pressure = Number(match[2]);
let humidity = Number(match[3]);

// Validate readings
if (
    !Number.isFinite(temperature) ||
    !Number.isFinite(pressure) ||
    !Number.isFinite(humidity) ||
    humidity < 0 || humidity > 100
) {
    node.warn("Invalid STM32 sensor readings");
    return null;
}

// Create JSON object
msg.payload = {
    temperature_c: temperature,
    humidity_pct: humidity,
    pressure_hpa: pressure
};

return msg;
